async function* readArchive(chunks) {
  const source = chunks[Symbol.asyncIterator]();
  const decoder = new TextDecoder("utf-8", { fatal: true });
  let parts = [];
  let length = 0;
  let line = 1;
  let eof = false;
  let closed = false;

  function append(bytes) {
    if (bytes.length) {
      parts.push(bytes);
      length += bytes.length;
    }
  }

  function takeLine() {
    const bytes = new Uint8Array(length);
    let offset = 0;

    for (const part of parts) {
      bytes.set(part, offset);
      offset += part.length;
    }

    parts = [];
    length = 0;

    const end = bytes.length && bytes[bytes.length - 1] === 13
      ? bytes.length - 1
      : bytes.length;

    return decoder.decode(bytes.subarray(0, end));
  }

  function parseRecord(text, physicalLine) {
    if (text.trim() === "") return { empty: true };

    try {
      return { value: JSON.parse(text) };
    } catch (cause) {
      const error = new SyntaxError(cause.message);
      error.code = "INVALID_RECORD";
      error.line = physicalLine;
      throw error;
    }
  }

  try {
    for (;;) {
      const next = await source.next();

      if (next.done) {
        eof = true;

        if (length) {
          const record = parseRecord(takeLine(), line);
          if (!record.empty) yield record.value;
        }

        return;
      }

      const chunk = next.value;

      for (let start = 0; start < chunk.length;) {
        const newline = chunk.indexOf(10, start);

        if (newline === -1) {
          append(chunk.subarray(start));
          break;
        }

        append(chunk.subarray(start, newline));
        const record = parseRecord(takeLine(), line++);
        start = newline + 1;

        if (!record.empty) yield record.value;
      }
    }
  } finally {
    if (!eof && !closed && typeof source.return === "function") {
      closed = true;
      await source.return();
    }
  }
}
